namespace MultiAiConnector.Engines.AI.Perplexity.Models;

/// <summary>
/// Represents a response choice generated by the Perplexity AI model.
/// </summary>
public class Choice
{
    /// <summary>
    /// The index of this choice within the array of choices offered by Perplexity.
    /// </summary>
    public int index { get; set; }

    /// <summary>
    /// The reason why the text generation finished (e.g., 'length', 'stop_sequences').
    /// Might require referring to Perplexity's documentation.
    /// </summary>
    public string finish_reason { get; set; } 

    /// <summary>
    /// The generated text content of the choice.
    /// </summary>
    public Message message { get; set; } 

    /// <summary>
    /// (Possibly) Represents changes or updates to the prompt or context within the generation.
    /// This requires further investigation of the Perplexity API.
    /// </summary>
    public Delta delta { get; set; } 
}
